// Returns intersection of two sorted arrays
function findIntersection(arr1, arr2) {
  let i = 0, j = 0;
  const intersection = [];

  while (i < arr1.length && j < arr2.length) {
    if (arr1[i] === arr2[j]) {
      intersection.push(arr1[i]);
      i++;
      j++;
    } else if (arr1[i] < arr2[j]) {
      i++;
    } else {
      j++;
    }
  }

  return intersection;
}

